import { CognitoIdentityProviderClient, ListUsersCommand } from '@aws-sdk/client-cognito-identity-provider';
import { log } from '../http/log';

/**
 * Chặn 1 hộp thư tạo nhiều tài khoản bằng email bí danh (QA #140: "ten+1@gmail.com", "ten+2@…", "t.e.n@gmail.com").
 * Mỗi tài khoản có hạn mức tin, đánh giá, uy tín riêng → nhiều tài khoản của cùng một người làm sai các con số đó.
 * Trùng email y hệt thì Cognito đã tự chặn (email là alias). Trigger PreSignUp của user pool gọi hàm này.
 */

/** Email chuẩn hóa của một hộp thư: chữ thường, bỏ "+nhãn"; Gmail bỏ dấu chấm và coi googlemail.com là gmail.com. */
export function canonicalEmail(email: string): string {
  const at = email.trim().toLowerCase().lastIndexOf('@');
  if (at < 1) return email.trim().toLowerCase();
  const raw = email.trim().toLowerCase();
  let local = raw.slice(0, at).split('+')[0]!;
  let domain = raw.slice(at + 1);
  if (domain === 'googlemail.com') domain = 'gmail.com';
  if (domain === 'gmail.com') local = local.replace(/\./g, '');
  return `${local}@${domain}`;
}

export interface ExistingUser {
  email: string;
  confirmed: boolean;
}

/** Tìm tài khoản theo email: `=` đúng email, `^=` email bắt đầu bằng. */
export type FindUsers = (filter: { op: '=' | '^='; value: string }) => Promise<ExistingUser[]>;

/** Trả lý do chặn, hoặc undefined nếu được đăng ký. Chỉ tính tài khoản đã xác minh email. */
export async function aliasConflict(email: string, find: FindUsers): Promise<string | undefined> {
  const canon = canonicalEmail(email);
  const local = canon.slice(0, canon.lastIndexOf('@'));
  const typedBase = email.trim().toLowerCase().replace(/\+[^@]*@/, '@');
  const lookups = [
    { op: '=' as const, value: canon },
    { op: '=' as const, value: typedBase },
    { op: '^=' as const, value: `${local}+` },
  ];
  const found = (await Promise.all(lookups.map(find))).flat();
  const clash = found.find((u) => u.confirmed && canonicalEmail(u.email) === canon && u.email.toLowerCase() !== email.trim().toLowerCase());
  if (!clash) return undefined;
  return 'Hộp thư này đã có tài khoản ReLoop (email bí danh có dấu "+" hoặc dấu chấm vẫn là cùng một hộp thư). Hãy đăng nhập bằng tài khoản đã có hoặc dùng "Quên mật khẩu".';
}

interface PreSignUpEvent {
  triggerSource: string;
  userPoolId: string;
  request: { userAttributes: Record<string, string> };
  response: Record<string, unknown>;
}

export const isPreSignUp = (event: unknown): event is PreSignUpEvent =>
  typeof event === 'object' && event !== null && typeof (event as { triggerSource?: unknown }).triggerSource === 'string' &&
  (event as { triggerSource: string }).triggerSource.startsWith('PreSignUp_');

const cognito = new CognitoIdentityProviderClient({});

/** Trigger PreSignUp: ném lỗi = Cognito từ chối đăng ký (web hiện lý do). Lỗi tra cứu → cho qua, không chặn người dùng thật. */
export async function handlePreSignUp(event: PreSignUpEvent): Promise<PreSignUpEvent> {
  if (event.triggerSource !== 'PreSignUp_SignUp') return event; // Admin tạo tài khoản: không kiểm
  const email = event.request.userAttributes.email;
  if (!email) return event;
  const find: FindUsers = async ({ op, value }) => {
    const r = await cognito.send(new ListUsersCommand({ UserPoolId: event.userPoolId, Filter: `email ${op} "${value.replace(/"/g, '')}"`, Limit: 20 }));
    return (r.Users ?? []).map((u) => ({
      email: u.Attributes?.find((a) => a.Name === 'email')?.Value ?? '',
      confirmed: u.UserStatus !== 'UNCONFIRMED',
    }));
  };
  let reason: string | undefined;
  try {
    reason = await aliasConflict(email, find);
  } catch (err) {
    log('error', 'presignup_lookup_failed', { error: err instanceof Error ? err.message : String(err) });
    return event;
  }
  if (reason) {
    log('info', 'presignup_alias_blocked', {});
    throw new Error(reason);
  }
  return event;
}
