import type { Clock } from '../../shared/clock';
import { conflict, notFound } from '../../shared/errors';
import { newId } from '../../shared/ids';
import { oneOf, str } from '../../shared/validate';
import { gsi1, keys } from '../../store/keys';
import { pageQuery } from '../../store/paging';
import { withOptimisticRetry } from '../../store/retry';
import { putNew, putVersioned, type Item, type Table } from '../../store/table';
import type { NotificationService } from '../notifications/notificationService';

export const SUPPORT_STATUSES = ['OPEN', 'ANSWERED', 'CLOSED'] as const;
export type SupportStatus = (typeof SUPPORT_STATUSES)[number];

/** Tối đa tin trong 1 yêu cầu (lưu chung item, giữ dưới giới hạn 400 KB của DynamoDB) — dài hơn thì mở yêu cầu mới. */
const MAX_MESSAGES = 60;

export interface SupportMessage {
  by: 'USER' | 'ADMIN';
  text: string;
  at: string;
  adminId?: string;
}

export interface SupportTicket extends Item {
  ticketId: string;
  userId: string;
  /** Email / tên người gửi lúc tạo — Admin xem nhanh trong hộp thư */
  userLabel?: string;
  subject: string;
  status: SupportStatus;
  messages: SupportMessage[];
  createdAt: string;
  updatedAt: string;
}

/**
 * Hộp thư hỗ trợ giữa người dùng / đối tác và Admin (PO 2026-10-30 — thay các mục "Coming soon": Tin nhắn + Trung tâm hỗ trợ
 * của Admin, "Kênh liên hệ trực tiếp" của đối tác). OPEN = chờ Admin trả lời · ANSWERED = Admin đã trả lời · CLOSED = đã đóng
 * (người dùng nhắn thêm thì mở lại).
 */
export class SupportService {
  constructor(
    private readonly table: Table,
    private readonly clock: Clock,
    private readonly notifications: NotificationService,
  ) {}

  async create(userId: string, userLabel: string | undefined, input: Record<string, unknown>): Promise<SupportTicket> {
    const subject = str(input.subject, 'subject', { min: 3, max: 120 })!;
    const text = str(input.message, 'message', { min: 5, max: 2000 })!;
    const now = this.clock.now().toISOString();
    const ticketId = newId();
    const ticket: SupportTicket = {
      ...keys.supportTicket(ticketId),
      ...gsi1.byStatus('SUPPORT', 'OPEN', `${now}#${ticketId}`),
      ticketId,
      userId,
      userLabel,
      subject,
      status: 'OPEN',
      messages: [{ by: 'USER', text, at: now }],
      createdAt: now,
      updatedAt: now,
    };
    await this.table.transact([putVersioned(ticket, 0), putNew({ ...keys.userSupport(userId, now, ticketId), ticketId })]);
    await this.notifications.notifyAdmins({ type: 'SUPPORT_NEW', title: `Yêu cầu hỗ trợ mới: ${subject}`, body: userLabel, link: `/admin/messages?t=${ticketId}` });
    return { ...ticket, version: 1 };
  }

  /** Yêu cầu của chính mình, mới nhất trước. */
  async listMine(userId: string): Promise<SupportTicket[]> {
    const refs = await this.table.query<Item & { ticketId: string }>(keys.userPk(userId), { skPrefix: 'SUPPORT#', ascending: false, limit: 50 });
    const tickets = await Promise.all(refs.map((r) => this.load(r.ticketId).catch(() => undefined)));
    return tickets.filter((t): t is SupportTicket => !!t);
  }

  listByStatus(rawStatus: unknown, cursor?: string) {
    const status = oneOf<SupportStatus>(rawStatus ?? 'OPEN', SUPPORT_STATUSES, 'status');
    return pageQuery<SupportTicket>(this.table, gsi1.statusPk('SUPPORT', status), { index: 'gsi1', cursor });
  }

  /** Người dùng nhắn thêm → về OPEN (chờ Admin). */
  async userReply(userId: string, ticketId: string, input: Record<string, unknown>): Promise<SupportTicket> {
    const text = str(input.text, 'text', { min: 1, max: 2000 })!;
    return this.change(ticketId, (t, now) => {
      if (t.userId !== userId) throw notFound('yêu cầu hỗ trợ');
      return { ...t, status: 'OPEN', messages: [...t.messages, { by: 'USER', text, at: now }] };
    });
  }

  async adminReply(adminId: string, ticketId: string, input: Record<string, unknown>): Promise<SupportTicket> {
    const text = str(input.text, 'text', { min: 1, max: 2000 })!;
    const t = await this.change(ticketId, (cur, now) => ({ ...cur, status: 'ANSWERED', messages: [...cur.messages, { by: 'ADMIN', text, at: now, adminId }] }));
    await this.notifications.notify(t.userId, { type: 'SUPPORT_ANSWERED', title: `Admin đã trả lời: ${t.subject}`, body: text.slice(0, 140), link: `/support?t=${ticketId}` });
    return t;
  }

  close(ticketId: string): Promise<SupportTicket> {
    return this.change(ticketId, (t) => {
      if (t.status === 'CLOSED') throw conflict('SUPPORT_CLOSED', 'Yêu cầu đã đóng');
      return { ...t, status: 'CLOSED' };
    });
  }

  async load(ticketId: string): Promise<SupportTicket> {
    const k = keys.supportTicket(ticketId);
    const t = await this.table.get<SupportTicket>(k.pk, k.sk);
    if (!t) throw notFound('yêu cầu hỗ trợ');
    return t;
  }

  private change(ticketId: string, fn: (t: SupportTicket, now: string) => SupportTicket): Promise<SupportTicket> {
    return withOptimisticRetry(async () => {
      const current = await this.load(ticketId);
      const now = this.clock.now().toISOString();
      const next = fn(current, now);
      if (next.messages.length > MAX_MESSAGES) throw conflict('SUPPORT_TOO_LONG', 'Cuộc trao đổi đã quá dài — hãy gửi yêu cầu hỗ trợ mới');
      const item: SupportTicket = { ...next, ...gsi1.byStatus('SUPPORT', next.status, `${now}#${ticketId}`), updatedAt: now };
      await this.table.transact([putVersioned(item, current.version ?? 1)]);
      return { ...item, version: (current.version ?? 1) + 1 };
    });
  }
}
