import { badRequest, AppError } from '../shared/errors';

/**
 * Phiên đăng nhập web bằng cookie HttpOnly (QA #19): refresh token Cognito không còn nằm trong localStorage
 * (script trên trang — kể cả mã độc chèn qua XSS — không đọc được). Web gọi /api/auth/* cùng tên miền (CloudFront → API Gateway),
 * nhận idToken giữ trong bộ nhớ tab; hết hạn thì gọi /api/auth/refresh, cookie tự đi kèm.
 */
export const SESSION_COOKIE = 'rl_rt';
/** Đường dẫn phía trình duyệt (CloudFront /api/auth/* → Lambda /auth/*) — cookie chỉ gửi tới 3 route này. */
const COOKIE_PATH = '/api/auth';
/** Bằng hạn refresh token của app client web (Terraform refresh_token_validity = 5 ngày). */
const REMEMBER_SECONDS = 5 * 24 * 3600;

export interface IssuedToken {
  idToken: string;
  /** giây */
  expiresIn: number;
}

export interface TokenRefresher {
  readonly enabled: boolean;
  /** Đổi refresh token lấy idToken mới; refresh token sai / bị thu hồi / hết hạn → ném AppError 401. */
  refresh(refreshToken: string): Promise<IssuedToken>;
  /** Thu hồi refresh token khi đăng xuất (lỗi bỏ qua). */
  revoke(refreshToken: string): Promise<void>;
}

const sessionInvalid = () => new AppError(401, 'SESSION_INVALID', 'Phiên đăng nhập đã hết hạn — vui lòng đăng nhập lại');

/** Gọi API công khai của Cognito (app client web không có secret → không cần quyền IAM). */
export class CognitoRefresher implements TokenRefresher {
  readonly enabled = true;
  constructor(
    private readonly clientId: string,
    private readonly region: string,
  ) {}

  private async idp<T>(action: string, body: Record<string, unknown>): Promise<T> {
    const res = await fetch(`https://cognito-idp.${this.region}.amazonaws.com/`, {
      method: 'POST',
      headers: { 'content-type': 'application/x-amz-json-1.1', 'x-amz-target': `AWSCognitoIdentityProviderService.${action}` },
      body: JSON.stringify({ ClientId: this.clientId, ...body }),
    });
    if (!res.ok) throw sessionInvalid();
    return (await res.json()) as T;
  }

  async refresh(refreshToken: string): Promise<IssuedToken> {
    const r = await this.idp<{ AuthenticationResult?: { IdToken?: string; ExpiresIn?: number } }>('InitiateAuth', {
      AuthFlow: 'REFRESH_TOKEN_AUTH',
      AuthParameters: { REFRESH_TOKEN: refreshToken },
    });
    const idToken = r.AuthenticationResult?.IdToken;
    if (!idToken) throw sessionInvalid();
    return { idToken, expiresIn: r.AuthenticationResult?.ExpiresIn ?? 3600 };
  }

  async revoke(refreshToken: string): Promise<void> {
    await this.idp('RevokeToken', { Token: refreshToken }).catch(() => undefined);
  }
}

/** Dev local (AUTH_MODE=local) không có Cognito. */
export class DisabledRefresher implements TokenRefresher {
  readonly enabled = false;
  async refresh(): Promise<IssuedToken> {
    throw new AppError(404, 'COOKIE_SESSION_DISABLED', 'Môi trường này không dùng phiên cookie');
  }
  async revoke(): Promise<void> {}
}

export const sessionCookie = (refreshToken: string, remember: boolean) =>
  // Không "Ghi nhớ đăng nhập" → cookie phiên, đóng trình duyệt là mất (như sessionStorage trước đây)
  `${SESSION_COOKIE}=${refreshToken}; Path=${COOKIE_PATH}; HttpOnly; Secure; SameSite=Strict${remember ? `; Max-Age=${REMEMBER_SECONDS}` : ''}`;

export const clearedCookie = () => `${SESSION_COOKIE}=; Path=${COOKIE_PATH}; HttpOnly; Secure; SameSite=Strict; Max-Age=0`;

/** Đọc cookie từ event API Gateway v2 (mảng `cookies`) hoặc header Cookie. */
export function parseCookies(list: string[] | undefined, header: string | undefined): Record<string, string> {
  const parts = list ?? (header ? header.split(';') : []);
  const out: Record<string, string> = {};
  for (const p of parts) {
    const i = p.indexOf('=');
    if (i > 0) out[p.slice(0, i).trim()] = p.slice(i + 1).trim();
  }
  return out;
}

/**
 * Chống CSRF: ngoài SameSite=Strict, bắt buộc header tự đặt (trình duyệt không cho trang khác gửi header lạ mà không qua preflight CORS,
 * mà /api/auth/* không bật CORS cho nguồn khác).
 */
export function requireAuthHeader(headers: Record<string, string | undefined>) {
  if (headers['x-reloop-auth'] !== '1') throw badRequest('AUTH_HEADER_REQUIRED', 'Thiếu header x-reloop-auth');
}
